using System;using System.IO;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using System.Text.RegularExpressions;
// Production vector geometry for the approved C / Kaiwu K identity.
static class RenderBrand {
 const string Ink="#F4F8F2",Paper="#1B665A",Lime="#9ADCB5",Edge="#347F6D";
 const string Body="M 57 194 L 57 80 C 57 67 63 61 77 61 L 106 61 C 109 61 110 62 110 65 L 110 129 C 124 125 138 127 148 137 L 201 184 C 207 190 205 194 197 194 L 166 194 C 161 194 158 192 155 189 L 119 150 C 113 143 110 145 110 155 L 110 190 C 110 193 109 194 106 194 Z";
 const string Leaf="M 119 105 L 155 67 C 159 63 162 61 169 61 L 198 61 C 204 61 206 64 201 69 L 164 107 C 161 110 158 111 153 111 L 121 111 C 116 111 116 109 119 105 Z";
 static GraphicsPath Shape(string d){var tokens=Regex.Matches(d,@"[MLCZ]|-?\d+(?:\.\d+)?");int i=0;float x=0,y=0;var p=new GraphicsPath();Func<float> n=()=>float.Parse(tokens[i++].Value,System.Globalization.CultureInfo.InvariantCulture);while(i<tokens.Count){string c=tokens[i++].Value;if(c=="M"){x=n();y=n();p.StartFigure();}else if(c=="L"){float a=n(),b=n();p.AddLine(x,y,a,b);x=a;y=b;}else if(c=="C"){float a=n(),b=n(),c1=n(),d1=n(),e=n(),f=n();p.AddBezier(x,y,a,b,c1,d1,e,f);x=e;y=f;}else if(c=="Z")p.CloseFigure();else throw new Exception("Invalid logo path");}return p;}
 static GraphicsPath Tile(){var p=new GraphicsPath();p.AddArc(8,8,116,116,180,90);p.AddArc(132,8,116,116,270,90);p.AddArc(132,132,116,116,0,90);p.AddArc(8,132,116,116,90,90);p.CloseFigure();return p;}
 static void Main(string[] args){string output=args[0];Directory.CreateDirectory(output);string svg="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"256\" height=\"256\" viewBox=\"0 0 256 256\"><title>Kaiwu</title><rect x=\"8\" y=\"8\" width=\"240\" height=\"240\" rx=\"58\" fill=\""+Paper+"\" stroke=\""+Edge+"\" stroke-width=\"6\"/><g transform=\"translate(-33.28 -43.52) scale(1.26 1.34)\"><path fill=\""+Ink+"\" d=\""+Body+"\"/><path fill=\""+Lime+"\" d=\""+Leaf+"\"/></g></svg>";File.WriteAllText(Path.Combine(output,"app-icon.svg"),svg,new System.Text.UTF8Encoding(false));
  foreach(int size in new[]{16,24,32,48,64,128,256,1024})using(var image=new Bitmap(size,size,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);g.SmoothingMode=SmoothingMode.AntiAlias;g.ScaleTransform(size/256f,size/256f);using(var tile=Tile())using(var paper=new SolidBrush(ColorTranslator.FromHtml(Paper)))using(var pen=new Pen(ColorTranslator.FromHtml(Edge),Math.Max(6f,256f/size))){g.FillPath(paper,tile);g.DrawPath(pen,tile);}g.TranslateTransform(-33.28f,-43.52f);g.ScaleTransform(1.26f,1.34f);using(var path=Shape(Body))using(var brush=new SolidBrush(ColorTranslator.FromHtml(Ink)))g.FillPath(brush,path);using(var path=Shape(Leaf))using(var brush=new SolidBrush(ColorTranslator.FromHtml(Lime)))g.FillPath(brush,path);}string name=size==256?"app-icon.png":size==1024?"app-icon-1024.png":"icon-sizes/"+size+".png";Directory.CreateDirectory(Path.GetDirectoryName(Path.Combine(output,name)));image.Save(Path.Combine(output,name),ImageFormat.Png);}
 }
}
